// Prepare Run Summary — safe when Mark nodes skip (n8n 2.x)
const cfg = $('config').first().json;

const safeAll = (nodeName) => {
  try {
    return $(nodeName).all();
  } catch (e) {
    return [];
  }
};

const enriched = safeAll('Mark Enriched');
const noEmail = safeAll('Mark No Email');
const failed = safeAll('Mark Enrich Failed (retry or terminal)');

const successCount = enriched.length;
const noEmailCount = noEmail.length;
const failedCount = failed.length;

const leadIds = [...enriched, ...noEmail, ...failed]
  .map((i) => i.json.id)
  .filter(Boolean)
  .join(',');

const start = new Date(cfg.runStartTs).getTime();
const durationMs = Number.isFinite(start) ? Date.now() - start : 0;

return [{
  json: {
    workflow_name: cfg.workflowName || 'enrichment',
    leads_processed: successCount + noEmailCount,
    leads_failed: failedCount,
    duration_ms: durationMs,
    notes:
      'WF2 enrichment | enriched=' + successCount +
      ' no_email=' + noEmailCount +
      ' failed=' + failedCount +
      ' | batch_ids: ' + (leadIds || 'none'),
  },
}];
